        M_ej_wind = 0.04 * M_sun  # kg
        M_ej_total = M_ej_dynamical + M_ej_wind
        
        # Velocities
        v_dynamical = 0.2 * c  # m/s
        v_wind = 0.1 * c  # m/s
        
        # Electron fractions
