        a_star = dataset.get('a_star', 0.9)
        B = dataset.get('B', 1)  # Tesla (10^4 Gauss)
        
        r_g = G * M / c**2
        r_plus = r_g * (1 + np.sqrt(1 - a_star**2))
        
        # Horizon area
        A_H = 4 * np.pi * (r_plus**2 + (a_star * r_g)**2)
        
        # Magnetic flux
        Phi_B = B * A_H
        
        # BZ power (approximate formula)
