        import math
        P = ORB_ANALYSIS_61_PARAMS
        
        efficiency_base = efficiency_base if efficiency_base is not None else P['reactor_efficiency']
        f_plasma = f_plasma if f_plasma is not None else P['plasma_freq']
        
